const {Scope} = ExpressiveUI.core;
const {createMorph,createShapeRenderer,cubicPathDiscontinuity} = ExpressiveUI.shape;
const {createSpring,motionPreset} = ExpressiveUI.motion;

async function mount(root){
const scope=new Scope();
const $=(id)=>root.querySelector('#'+id);
try {
const pair=createMorph('circle','flower');await pair.ready;const renderer=createShapeRenderer($('shape'),'svg');scope.add(()=>renderer.destroy());const spring=createSpring(0,value=>{const path=pair.cubicsAt(value);renderer.drawCubics(path);$('output').textContent='C0 seam: '+cubicPathDiscontinuity(path);},motionPreset());scope.add(()=>spring.destroy());spring.setTarget(1);
} catch(error) {scope.dispose();throw error;}
return ()=>scope.dispose();
}
mount(document.getElementById("example")).then(cleanup => {
  addEventListener("pagehide", cleanup, {once: true});
}).catch(console.error);

