const {Scope} = ExpressiveUI.core;
const {generateTheme,createThemeController} = ExpressiveUI.theme;

async function mount(root){
const scope=new Scope();
const $=(id)=>root.querySelector('#'+id);
try {
const light=generateTheme({seed:'#157A6E',variant:'expressive'});const dark=generateTheme({seed:'#157A6E',variant:'expressive',dark:true});const theme=createThemeController(root,{light,dark},'light');scope.add(()=>theme.destroy());for(const role of ['primary','secondary','tertiary'] ){const swatch=document.createElement('div');swatch.textContent=role;swatch.style.cssText='padding:24px;border-radius:20px;background:'+light.colors[role]+';color:'+light.colors[('on'+role.charAt(0).toUpperCase()+role.slice(1)) ];$('palette').append(swatch);}
} catch(error) {scope.dispose();throw error;}
return ()=>scope.dispose();
}
